import React from 'react'

function ReviewsSection() {
    return (
        <div className="reviews w-full min-h-[510px] flex justify-center items-start py-10">
            <div className="w-[90%] min-h-[450px] bg-gray-100 rounded-lg p-6">
                
                {/* Верхняя панель */}
                <div className="w-full min-h-[70px] grid grid-cols-1 md:grid-cols-2 gap-4 items-center mb-6">
                    
                    {/* Заголовок */}
                    <div className="flex items-center">
                        <h2 className="font-semibold text-2xl md:text-3xl text-gray-800">
                            What our customers say!
                        </h2>
                    </div>

                    {/* Инфо о рейтинге */}
                    <div className="flex md:justify-end items-center text-sm md:text-base text-gray-600">
                        <span className="bg-white px-4 py-2 rounded shadow-sm">
                            ⭐ Rated <strong>4.7 / 5</strong> based on <strong>28,370</strong> reviews. Showing our 4 & 5 star reviews.
                        </span>
                    </div>
                </div>

                {/* Здесь можно разместить отзывы */}
                <div>
                    {/* Отзывы... */}
                </div>
            </div>
        </div>
    )
}

export default ReviewsSection;
